<template>
  <main class="operations" v-loading="busy">
    <header><div><h1>业务工作台</h1><p>库存有据可查，采购与调整经过审批后生效。</p></div><el-button @click="load">刷新</el-button></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <el-tabs v-model="tab" @tab-change="changeTab">
      <el-tab-pane label="库存与成本账本" name="inventory">
        <el-alert title="成本显示“待核定”时，请核定历史库存总成本后提交成本核定单。新入库费用计入移动平均成本。" :closable="false" />
        <el-table :data="rows"><el-table-column prop="id" label="库存ID" width="90"/><el-table-column prop="sku_code" label="SKU"/><el-table-column prop="goods_name" label="商品"/><el-table-column prop="warehouse_id" label="仓库" width="90"/><el-table-column prop="quantity" label="总量"/><el-table-column prop="locked_quantity" label="锁定"/><el-table-column prop="available_quantity" label="可用"/><el-table-column label="库存价值（元）"><template #default="{row}">{{ row.stock_value ?? '待核定' }}</template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link @click="showLedger(row)">流水</el-button><el-button link :disabled="!can('write')" @click="newDraft(row)">制单</el-button><el-button link :disabled="!can('write')" @click="newRule(row)">补货规则</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="单据与审批" name="documents">
        <p>制单人与审批人分离；大额或成本未知的单据需要第二人审批。已记账单据撤销会追加冲销流水。</p>
        <el-table :data="rows"><el-table-column label="单号" min-width="190"><template #default="{row}"><el-button link @click="showDocument(row)">{{ row.id }}</el-button></template></el-table-column><el-table-column label="类型"><template #default="{row}">{{ kinds[row.kind] }}</template></el-table-column><el-table-column prop="inventory_id" label="库存ID"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="received_quantity" label="已收货"/><el-table-column label="状态"><template #default="{row}"><el-tag>{{ states[row.state] }}</el-tag></template></el-table-column><el-table-column prop="purchase_id" label="采购单ID"/><el-table-column label="处理" width="110"><template #default="{row}"><el-button link @click="showDocument(row)">打开单据</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="补货建议" name="replenishment">
        <el-alert title="建议计入工作台未完成采购。其他入口的采购在途暂未计入，请核对后生成草稿；日需求和交期由业务人员维护。" type="warning" :closable="false" />
        <el-table :data="rows"><el-table-column prop="inventory_id" label="库存ID"/><el-table-column prop="sku_code" label="SKU"/><el-table-column prop="available_quantity" label="可用"/><el-table-column prop="open_purchase_quantity" label="未完成采购"/><el-table-column prop="projected_quantity" label="预计库存"/><el-table-column prop="effective_reorder_point" label="补货点"/><el-table-column prop="suggested_quantity" label="建议数量"/><el-table-column label="操作" width="200"><template #default="{row}"><el-button link :disabled="!can('write')" @click="editRule(row)">规则</el-button><el-button type="primary" size="small" :disabled="!can('write') || !row.suggested_quantity" @click="replenish(row)">采购草稿</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane v-if="admin" label="审批规则" name="policies">
        <p>每种单据可配置审批权限与二审金额门槛；修改只影响之后提交的单据。</p>
        <el-table :data="rows"><el-table-column label="类型"><template #default="{row}">{{ kinds[row.kind] }}</template></el-table-column><el-table-column label="二审门槛（元）"><template #default="{row}"><el-input-number v-model="row.threshold_amount" :min="0" :precision="2" /></template></el-table-column><el-table-column label="一级审批"><template #default="{row}"><el-select v-model="row.first_permission"><el-option label="业务审批" value="erp:operations:approve"/><el-option label="财务审批" value="erp:operations:finance"/></el-select></template></el-table-column><el-table-column label="二级审批"><template #default="{row}"><el-select v-model="row.second_permission"><el-option label="财务审批" value="erp:operations:finance"/><el-option label="业务审批" value="erp:operations:approve"/></el-select></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button @click="savePolicy(row)">保存</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane v-if="admin" label="数据授权" name="grants">
        <el-alert title="授权账号将通过工作台及受限 AI 查询数据；旧业务接口会被阻止，防止绕过范围。商户必须明确，店铺或仓库填 -1 表示该商户下全部。另需在角色菜单中授予工作台操作权限。" type="warning" :closable="false" />
        <el-form inline class="form-row"><el-form-item label="用户ID"><el-input-number v-model="grant.userId" :min="1" /></el-form-item><el-form-item label="商户ID"><el-input-number v-model="grant.merchantId" :min="0" /></el-form-item><el-form-item label="店铺ID"><el-input-number v-model="grant.shopId" :min="-1" /></el-form-item><el-form-item label="仓库ID"><el-input-number v-model="grant.warehouseId" :min="-1" /></el-form-item><el-button type="primary" @click="saveGrant">授权</el-button></el-form>
        <el-table :data="rows"><el-table-column prop="user_id" label="用户ID"/><el-table-column prop="merchant_id" label="商户ID"/><el-table-column prop="shop_id" label="店铺ID"/><el-table-column prop="warehouse_id" label="仓库ID"/><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" @click="removeGrant(row)">撤销</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="商品与供应商扩展" name="master">
        <el-form inline><el-form-item label="类型"><el-select v-model="masterKind" style="width:160px"><el-option value="PRODUCT" label="商品"/><el-option value="SUPPLIER" label="供应商"/></el-select></el-form-item><el-form-item label="记录ID"><el-input-number v-model="masterId" :min="1"/></el-form-item><el-button @click="loadMaster">读取</el-button></el-form>
        <el-form v-if="masterData.recordId" label-position="top"><p>{{ allKinds[masterData.kind] }} #{{ masterData.recordId }}</p><FieldEditor :fields="masterData.fields" :values="masterData.attributes"/><el-empty v-if="!masterData.fields.length" description="尚未定义扩展字段，请管理员先配置"/><el-button v-else type="primary" :disabled="!can('write')" @click="saveMaster">保存扩展信息</el-button></el-form>
      </el-tab-pane>
      <el-tab-pane v-if="admin" label="扩展字段" name="fields">
        <el-select v-model="fieldKind" @change="load"><el-option v-for="(label,key) in allKinds" :key="key" :value="key" :label="label"/></el-select><el-button @click="fieldOpen=true">新建字段</el-button>
        <p>新增字段自动出现在制单表单中。支持文本、数值、日期、选项与开关；必填及格式由服务端验证。</p>
        <el-table :data="rows"><el-table-column prop="field_key" label="字段键"/><el-table-column prop="label" label="名称"/><el-table-column prop="field_type" label="类型"/><el-table-column prop="required_flag" label="必填"/><el-table-column prop="options_json" label="选项"/></el-table>
      </el-tab-pane>
      <el-tab-pane v-if="admin" label="配置审计" name="audit"><el-table :data="rows"><el-table-column prop="document_id" label="对象"/><el-table-column prop="action" label="操作"/><el-table-column prop="actor_id" label="用户"/><el-table-column label="时间"><template #default="{row}">{{ time(row.created_at) }}</template></el-table-column><el-table-column prop="detail" label="变更内容" min-width="400"/></el-table></el-tab-pane>
    </el-tabs>
    <footer v-if="!['policies','grants','fields','master'].includes(tab)"><el-button :disabled="page===1" @click="page--;load()">上一页</el-button><span>第 {{ page }} 页 · 每页最多 50 条</span><el-button :disabled="rows.length<50" @click="page++;load()">下一页</el-button><el-button :disabled="!rows.length" @click="exportPage">导出本页</el-button></footer>
    <el-dialog v-model="draftOpen" title="新建业务单据" width="650px">
      <el-form label-position="top"><div class="grid"><el-form-item label="单据类型"><el-select v-model="draft.kind" @change="loadDraftFields"><el-option v-for="(label,key) in kinds" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item label="库存ID"><el-input-number v-model="draft.inventoryId" disabled/></el-form-item>
        <el-form-item v-if="draft.kind!=='VALUATION'" label="数量（盘点调整可填负数）"><el-input-number v-model="draft.quantity" :precision="0"/></el-form-item><el-form-item v-if="!['ISSUE','TRANSFER'].includes(draft.kind)" :label="draft.kind==='VALUATION'?'核定库存总成本（元）':'单位成本（元）'"><el-input-number v-model="draft.unitCost" :min="0" :precision="6" :value-on-clear="null"/></el-form-item><el-form-item v-if="['PURCHASE','RECEIPT','ADJUSTMENT'].includes(draft.kind)" label="附加费用（元）"><el-input-number v-model="draft.extraCost" :min="0" :precision="2"/></el-form-item><el-form-item v-if="draft.kind==='PURCHASE'" label="供应商ID"><el-input-number v-model="draft.supplierId" :min="1"/></el-form-item><el-form-item v-if="draft.kind==='TRANSFER'" label="目标库存ID（同SKU）"><el-input-number v-model="draft.targetInventoryId" :min="1"/></el-form-item></div>
        <el-form-item label="业务原因"><el-input v-model="draft.reason" type="textarea" maxlength="500"/></el-form-item>
        <el-form-item v-for="field in draftFields" :key="field.field_key" :label="field.label" :required="!!field.required_flag"><el-input-number v-if="field.field_type==='number'" v-model="draft.attributes[field.field_key]"/><el-date-picker v-else-if="field.field_type==='date'" v-model="draft.attributes[field.field_key]" value-format="YYYY-MM-DD"/><el-switch v-else-if="field.field_type==='boolean'" v-model="draft.attributes[field.field_key]"/><el-select v-else-if="field.field_type==='select'" v-model="draft.attributes[field.field_key]"><el-option v-for="option in JSON.parse(field.options_json)" :key="option" :value="option"/></el-select><el-input v-else v-model="draft.attributes[field.field_key]" maxlength="1000"/></el-form-item>
      </el-form><template #footer><el-button @click="draftOpen=false">返回</el-button><el-button type="primary" :loading="busy" @click="saveDraft">保存草稿</el-button></template>
    </el-dialog>
    <el-dialog v-model="ruleOpen" title="补货规则" width="650px"><el-form label-position="top" class="grid"><el-form-item v-for="(label,key) in ruleLabels" :key="key" :label="label"><el-input-number v-model="rule[key]" :min="key==='packSize'||key==='minOrder'||key==='supplierId'?1:0" :precision="key==='unitCost'?6:key==='dailyDemand'?4:0"/></el-form-item><el-form-item label="启用"><el-switch v-model="rule.enabled"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" @click="saveRule">保存规则</el-button></template></el-dialog>
    <el-dialog v-model="fieldOpen" title="定义扩展字段" width="540px"><el-form label-position="top"><el-form-item label="字段键（小写英文、数字、下划线）"><el-input v-model="field.key"/></el-form-item><el-form-item label="名称"><el-input v-model="field.label"/></el-form-item><el-form-item label="类型"><el-select v-model="field.type"><el-option v-for="(label,key) in fieldTypes" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="必填"><el-switch v-model="field.required"/></el-form-item><el-form-item v-if="field.type==='select'" label="选项（每行一个）"><el-input v-model="fieldOptions" type="textarea"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" @click="saveField">保存</el-button></template></el-dialog>
    <el-drawer v-model="ledgerOpen" title="库存流水" size="80%"><el-table :data="ledgerRows"><el-table-column prop="source" label="来源单据"/><el-table-column prop="quantity_delta" label="数量变动"/><el-table-column prop="locked_delta" label="锁定变动"/><el-table-column prop="quantity_after" label="结存数量"/><el-table-column label="结存价值"><template #default="{row}">{{ row.value_after ?? '待核定' }}</template></el-table-column><el-table-column prop="actor" label="操作人"/><el-table-column prop="reason" label="原因"/><el-table-column label="时间"><template #default="{row}">{{ time(row.created_at) }}</template></el-table-column></el-table><el-button :disabled="ledgerPage===1" @click="ledgerPage--;loadLedger()">上一页</el-button><el-button :disabled="ledgerRows.length<50" @click="ledgerPage++;loadLedger()">下一页</el-button></el-drawer>
    <el-drawer v-model="documentOpen" title="单据详情与审批" size="650px"><template v-if="selected.id"><h2>{{ kinds[selected.kind] }} · {{ states[selected.state] }}</h2><p>{{ selected.id }}</p><el-descriptions :column="2" border><el-descriptions-item label="库存ID">{{ selected.inventory_id }}</el-descriptions-item><el-descriptions-item label="数量">{{ selected.quantity }}</el-descriptions-item><el-descriptions-item label="制单人">{{ selected.created_by }}</el-descriptions-item><el-descriptions-item label="已收货">{{ selected.received_quantity }}</el-descriptions-item><el-descriptions-item label="单价/核定总成本">{{ selected.unit_cost ?? '—' }}</el-descriptions-item><el-descriptions-item label="费用">{{ selected.extra_cost }}</el-descriptions-item><el-descriptions-item label="原因">{{ selected.reason }}</el-descriptions-item></el-descriptions><p>扩展字段：{{ selected.attributes_json }}</p><el-input v-model="actionReason" type="textarea" placeholder="填写操作原因" maxlength="500"/><el-input-number v-if="selected.kind==='PURCHASE' && selected.state==='POSTED'" v-model="receiveQty" :min="1" :max="selected.quantity-selected.received_quantity"/>
      <div class="actions"><el-button v-for="action in availableActions" :key="action" :disabled="busy" @click="act(action)">{{ actionLabels[action] }}</el-button></div><h3>完整操作记录</h3><el-timeline><el-timeline-item v-for="entry in selected.history" :key="entry.id" :timestamp="time(entry.created_at)">{{ entry.actor_id }} · {{ entry.action }}<p>{{ entry.detail }}</p></el-timeline-item></el-timeline></template></el-drawer>
  </main>
</template>

<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { operations } from '@/api/operations'
import { useUserStore } from '@/store/modules/user'
import FieldEditor from './FieldEditor.vue'
const user=useUserStore(), admin=computed(()=>user.permissions.includes('*:*:*'))
const can=(action:string)=>admin.value||user.permissions.includes(`erp:operations:${action}`)
const kinds:Record<string,string>={PURCHASE:'采购',RECEIPT:'入库',ISSUE:'出库',ADJUSTMENT:'盘点调整',VALUATION:'成本核定',TRANSFER:'仓库调拨'}
const allKinds:Record<string,string>={...kinds,PRODUCT:'商品',SUPPLIER:'供应商'}
const masterKind=ref('PRODUCT'),masterId=ref(1),masterData=ref<any>({})
const states:Record<string,string>={DRAFT:'草稿',PENDING:'待一级审批',PENDING_SECOND:'待二级审批',APPROVED:'已批准',POSTED:'已生效',REJECTED:'已驳回',CANCELLED:'已取消'}
const actionLabels:Record<string,string>={submit:'提交审批',approve:'批准',reject:'驳回',post:'执行并记账',receive:'确认收货',cancel:'取消 / 冲销'}
const fieldTypes={text:'文本',number:'数值',date:'日期',select:'选项',boolean:'开关'}
const tab=ref('inventory'),page=ref(1),rows=ref<any[]>([]),busy=ref(false),error=ref('')
const draftOpen=ref(false),ruleOpen=ref(false),fieldOpen=ref(false),ledgerOpen=ref(false),documentOpen=ref(false)
const selected=ref<any>({}),ledgerRows=ref<any[]>([]),ledgerId=ref(0),ledgerPage=ref(1),draftFields=ref<any[]>([])
const actionReason=ref(''),receiveQty=ref(1),fieldKind=ref('PURCHASE'),fieldOptions=ref('')
const draft=ref<any>({}),rule=ref<any>({}),field=ref({key:'',label:'',type:'text',required:false,version:0})
const grant=ref({userId:2,merchantId:0,shopId:-1,warehouseId:-1,remove:false})
const ruleLabels:Record<string,string>={inventoryId:'库存ID',reorderPoint:'基础补货点',targetQuantity:'目标库存',minOrder:'最小采购量',packSize:'包装倍数',leadDays:'采购交期（天）',dailyDemand:'预计每日需求',supplierId:'供应商ID',unitCost:'采购单价（元）'}
const time=(value:number)=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
const availableActions=computed(()=>{const s=selected.value,actions:string[]=[];if(s.state==='DRAFT'&&can('write'))actions.push('submit');if(['PENDING','PENDING_SECOND'].includes(s.state)&&(admin.value||user.permissions.includes(s.state==='PENDING'?s.first_permission:s.second_permission)))actions.push('approve','reject');if(s.state==='APPROVED'&&can('post'))actions.push('post');if(s.state==='POSTED'&&s.kind==='PURCHASE'&&s.received_quantity<s.quantity&&can('post'))actions.push('receive');if(!['CANCELLED','REJECTED'].includes(s.state)&&can('write')&&(s.state!=='POSTED'||can('post')))actions.push('cancel');return actions})
async function safe(action:()=>Promise<void>){busy.value=true;error.value='';try{await action()}catch(e:any){if(e!=='cancel'&&e!=='close'){error.value=e.message||'操作失败';ElMessage.error(error.value)}}finally{busy.value=false}}
async function fetchRows(){if(tab.value==='master')return;rows.value=await operations(tab.value,'get',undefined,{page:page.value,kind:fieldKind.value})}
const load=()=>safe(fetchRows)
function changeTab(){page.value=1;rows.value=[];load()}
async function loadDraftFields(){draft.value.attributes={};draftFields.value=await operations('fields','get',undefined,{kind:draft.value.kind})}
function newDraft(row:any){draft.value={kind:'RECEIPT',inventoryId:row.id,quantity:1,unitCost:null,extraCost:0,supplierId:1,targetInventoryId:null,reason:'',attributes:{},requestKey:crypto.randomUUID()};safe(async()=>{await loadDraftFields();draftOpen.value=true})}
function saveDraft(){safe(async()=>{const d={...draft.value};if(d.kind==='VALUATION')d.quantity=0;if(['ISSUE','TRANSFER'].includes(d.kind)||d.kind==='ADJUSTMENT'&&d.quantity<0)d.unitCost=null;if(['PURCHASE','RECEIPT','VALUATION'].includes(d.kind)||d.kind==='ADJUSTMENT'&&d.quantity>0){if(d.unitCost==null||d.unitCost==='')throw new Error(d.kind==='VALUATION'?'请填写核定库存总成本':'请填写单位成本')}await operations('documents','post',d);draftOpen.value=false;tab.value='documents';page.value=1;await fetchRows();ElMessage.success('草稿已保存')})}
function showLedger(row:any){ledgerId.value=row.id;ledgerPage.value=1;ledgerOpen.value=true;loadLedger()}
function loadLedger(){safe(async()=>{ledgerRows.value=await operations(`ledger/${ledgerId.value}`,'get',undefined,{page:ledgerPage.value})})}
function showDocument(row:any){safe(async()=>{selected.value=await operations(`documents/${row.id}`);actionReason.value='';receiveQty.value=1;documentOpen.value=true})}
function act(action:string){safe(async()=>{if(!actionReason.value.trim())throw new Error('请填写操作原因');if(['post','cancel','receive'].includes(action))await ElMessageBox.confirm(`确认${actionLabels[action]}？此操作将更新业务数据。`,'确认业务操作');await operations(`documents/${selected.value.id}/actions`,'post',{action,version:selected.value.version,reason:actionReason.value,quantity:receiveQty.value});selected.value=await operations(`documents/${selected.value.id}`);await fetchRows();ElMessage.success('操作成功')})}
function newRule(row:any){rule.value={inventoryId:row.id,reorderPoint:10,targetQuantity:50,minOrder:1,packSize:1,leadDays:7,dailyDemand:0,supplierId:1,unitCost:0,enabled:true,version:0};ruleOpen.value=true}
function editRule(row:any){rule.value={inventoryId:row.inventory_id,reorderPoint:row.reorder_point,targetQuantity:row.target_quantity,minOrder:row.min_order,packSize:row.pack_size,leadDays:row.lead_days,dailyDemand:Number(row.daily_demand),supplierId:row.supplier_id,unitCost:Number(row.unit_cost),enabled:!!row.enabled,version:row.version};ruleOpen.value=true}
function saveRule(){safe(async()=>{await operations('replenishment','put',rule.value);ruleOpen.value=false;tab.value='replenishment';page.value=1;await fetchRows()})}
function replenish(row:any){safe(async()=>{const storageKey=`ef-replenish-${row.inventory_id}`;let key=sessionStorage.getItem(storageKey);if(!key){key=crypto.randomUUID();sessionStorage.setItem(storageKey,key)}await operations(`replenishment/${row.inventory_id}`,'post',{requestKey:key});sessionStorage.removeItem(storageKey);await fetchRows();ElMessage.success('采购草稿已生成，请在单据页核对并提交审批')})}
function savePolicy(row:any){safe(async()=>{await operations('policies','put',{kind:row.kind,threshold:row.threshold_amount,firstPermission:row.first_permission,secondPermission:row.second_permission,version:row.version});await fetchRows()})}
function saveGrant(){safe(async()=>{await operations('grants','put',grant.value);await fetchRows()})}
function removeGrant(row:any){safe(async()=>{await ElMessageBox.confirm('确认撤销此数据范围？','撤销授权');await operations('grants','put',{userId:row.user_id,merchantId:row.merchant_id,shopId:row.shop_id,warehouseId:row.warehouse_id,remove:true});await fetchRows()})}
function saveField(){safe(async()=>{await operations('fields','put',{...field.value,kind:fieldKind.value,options:fieldOptions.value.split('\n').filter(Boolean)});fieldOpen.value=false;field.value={key:'',label:'',type:'text',required:false,version:0};fieldOptions.value='';await fetchRows()})}
function loadMaster(){safe(async()=>{masterData.value={};masterData.value=await operations('master','get',undefined,{kind:masterKind.value,recordId:masterId.value})})}
function saveMaster(){safe(async()=>{const d=masterData.value;await operations('master','put',{kind:d.kind,recordId:d.recordId,version:d.version,attributes:d.attributes});masterData.value=await operations('master','get',undefined,{kind:d.kind,recordId:d.recordId});ElMessage.success('扩展信息已保存')})}
function exportPage(){const keys=Object.keys(rows.value[0]||{});const cell=(v:any)=>{let s=v==null?'':String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const csv='\uFEFF'+[keys,...rows.value.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`工作台-${tab.value}-第${page.value}页.csv`;a.click();URL.revokeObjectURL(url)}
onMounted(load)
</script>

